def naive_rag(question, store, k=5):
    hits    = store.search(embed(question), k=k)      # once
    context = "\n\n".join(h.text for h in hits)

    return model.generate(
        f"Answer from the context only.\n\n{context}\n\nQuestion: {question}"
    )

MAX_RETRIEVALS = 6

def should_stop(state):
    if state.retrievals >= MAX_RETRIEVALS:
        return "budget exhausted — report what was found and what was not"
    if state.last_two_queries_returned_same_docs():
        return "no new information — stop searching"
    if state.critic_says_sufficient():
        return "evidence sufficient — answer now"
    return None

